import type {
  NarrativeCheck,
  NarrativeCheckInput,
  NarrativeCheckResponse,
  NarrativeConsistencyChecker,
  NarrativeConsistencyOutcome,
} from "./domain.ts";

/** Builds the system prompt for the narrative-consistency check. */
export function buildNarrativeConsistencySystemPrompt(input: NarrativeCheckInput): string {
  return [
    "You are a claims narrative consistency evaluator.",
    "Compare the original claim narrative with the appraisal narrative.",
    "Return only JSON with one field: outcome.",
    'outcome must be exactly "CONSISTENT" or "CONTRADICTS".',
    "Do not assess coverage, damages, fraud, or payable amount.",
    "",
    "INPUT_JSON:",
    "```json",
    JSON.stringify(input, null, 2),
    "```"
  ].join("\n");
}

/** Returns the fixture-backed LLM response while consuming the fully injected prompt internally. */
function mockNarrativeResponse(
  systemPrompt: string,
  outcome: NarrativeConsistencyOutcome,
): NarrativeCheckResponse {
  if (!systemPrompt.includes("INPUT_JSON:")) {
    throw new Error("Narrative mock received an invalid system prompt.");
  }
  return { outcome };
}

/** Creates a deterministic checker that returns the outcome declared by a synthetic fixture. */
export function createFixtureNarrativeConsistencyChecker(
  outcome: NarrativeConsistencyOutcome,
): NarrativeConsistencyChecker {
  return {
    /** Returns the fixture-declared LLM response for the supplied narratives. */
    check(input: NarrativeCheckInput): NarrativeCheck {
      const response = mockNarrativeResponse(
        buildNarrativeConsistencySystemPrompt(input),
        outcome,
      );
      return {
        response,
        sourceRefs: input.sourceRefs,
      };
    },
  };
}

`n--- test/narrative-consistency.test.ts ---
import assert from "node:assert/strict";
import test from "node:test";
import {
  analyzeLiquidation,
  createFixtureNarrativeConsistencyChecker,
} from "../src/index.ts";
import { alignedInput } from "./fixtures.ts";

test("contradictory narratives block liquidation and leave the amount not computable", () => {
  const input = alignedInput();
  Object.assign(input.practice, { narrative: "The vehicle suffered rear-end collision damage." });
  Object.assign(input.appraisal, { narrative: "No collision damage was found on the vehicle." });

  const result = analyzeLiquidation(
    input,
    createFixtureNarrativeConsistencyChecker("CONTRADICTS"),
  );

  assert.equal(result.proposedDecision, "DO_NOT_LIQUIDATE");
  assert.equal(result.payableAmount, null);
  assert.equal(result.amountStatus, "NOT_COMPUTABLE");
  assert.equal(result.requiresHumanReview, true);
  assert.equal(result.narrativeCheck?.response.outcome, "CONTRADICTS");
  assert.equal("outcome" in (result.narrativeCheck ?? {}), false);
  assert.deepEqual(result.narrativeCheck?.response, { outcome: "CONTRADICTS" });
  assert.doesNotMatch(JSON.stringify(result), /systemPrompt/);
});

test("consistent narratives preserve the economic proposal", () => {
  const input = alignedInput();
  Object.assign(input.practice, { narrative: "The vehicle suffered rear-end collision damage." });
  Object.assign(input.appraisal, { narrative: "Rear-end collision damage was found on the vehicle." });

  const result = analyzeLiquidation(
    input,
    createFixtureNarrativeConsistencyChecker("CONSISTENT"),
  );

  assert.equal(result.proposedDecision, "LIQUIDATE");
  assert.deepEqual(result.payableAmount, { minorUnits: 90_00, currency: "EUR" });
  assert.equal(result.narrativeCheck?.response.outcome, "CONSISTENT");
  assert.equal("outcome" in (result.narrativeCheck ?? {}), false);
});

